        .map(function(p){ return +p.dataset.edge; })
        .sort(function(a, b){ return a - b; });
      if(!list.length){ return; }
      var stagger = list.length > 1 ? Math.min(60, 300 / (list.length - 1)) : 0;
      A.drawLines(list, {each:300, stagger:stagger, labels:true});
